import pandas as pd


def run(inputs: dict) -> dict:
    target = inputs["target_state"].copy()
    events = inputs["cdc_events"].copy()

    # --- 1. distinct by (order_id, seq) -- seq is only guaranteed unique
    #        per order; dedup must be keyed on the composite identity of
    #        an event, otherwise two different orders' events that happen
    #        to share the same seq value would be wrongly collapsed. ---
    events = events.drop_duplicates(subset=["order_id", "seq"], keep="first")

    # --- build initial state dict: order_id -> {status, amount, last_seq} ---
    state = {}
    for _, row in target.iterrows():
        oid = int(row["order_id"])
        state[oid] = {
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": int(row["last_seq"]),
        }

    # orders that ever had a row (initial target_state or created during batch)
    ever_had_row = set(state.keys())

    # replay guard is based on the INITIAL last_seq, fixed before any processing
    initial_last_seq = {oid: s["last_seq"] for oid, s in state.items()}

    def guard_ok(row):
        oid = int(row["order_id"])
        if oid in initial_last_seq:
            return row["seq"] > initial_last_seq[oid]
        return True

    if not events.empty:
        mask = events.apply(guard_ok, axis=1)
        events = events[mask]

    # process remaining events per order, in seq order
    events = events.sort_values(["order_id", "seq"])

    last_applied = {}  # order_id -> (seq, op) of the last applied event

    for _, ev in events.iterrows():
        oid = int(ev["order_id"])
        seq = int(ev["seq"])
        op = ev["op"]
        status = ev["status"]
        amount = ev["amount"]

        last_applied[oid] = (seq, op)

        if op in ("I", "U"):
            if oid in state:
                new_status = status
                if op == "U" and pd.isna(amount):
                    new_amount = state[oid]["amount"]
                else:
                    new_amount = amount
                state[oid] = {
                    "status": new_status,
                    "amount": new_amount,
                    "last_seq": seq,
                }
            else:
                state[oid] = {
                    "status": status,
                    "amount": amount,
                    "last_seq": seq,
                }
                ever_had_row.add(oid)
        elif op == "D":
            if oid in state:
                del state[oid]
            # D for a missing order: no-op

    # --- build new_state ---
    rows = []
    for oid, s in state.items():
        rows.append(
            {
                "order_id": oid,
                "status": s["status"],
                "amount": s["amount"],
                "last_seq": s["last_seq"],
            }
        )
    new_state = pd.DataFrame(rows, columns=["order_id", "status", "amount", "last_seq"])
    if new_state.empty:
        new_state = pd.DataFrame(
            {
                "order_id": pd.Series(dtype="int64"),
                "status": pd.Series(dtype=object),
                "amount": pd.Series(dtype="float64"),
                "last_seq": pd.Series(dtype="int64"),
            }
        )
    else:
        new_state["order_id"] = new_state["order_id"].astype("int64")
        new_state["last_seq"] = new_state["last_seq"].astype("int64")
        new_state["amount"] = new_state["amount"].astype("float64")

    # --- build tombstones ---
    tomb_rows = []
    for oid, (seq, op) in last_applied.items():
        if op == "D" and oid in ever_had_row:
            tomb_rows.append({"order_id": oid, "deleted_seq": seq})
    tombstones = pd.DataFrame(tomb_rows, columns=["order_id", "deleted_seq"])
    if tombstones.empty:
        tombstones = pd.DataFrame(
            {
                "order_id": pd.Series(dtype="int64"),
                "deleted_seq": pd.Series(dtype="int64"),
            }
        )
    else:
        tombstones["order_id"] = tombstones["order_id"].astype("int64")
        tombstones["deleted_seq"] = tombstones["deleted_seq"].astype("int64")

    return {"new_state": new_state, "tombstones": tombstones}
